#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;

constexpr ull MOD = 1000000007ULL;

ull modPow(ull base, ull exponent) {
    ull result = 1;
    base %= MOD;

    while (exponent > 0) {
        if (exponent & 1ULL) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1ULL;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ull n, m;
    cin >> n >> m;

    ull ans1 = (modPow(2, n) + MOD - 1) % MOD;
    ull ans2 = (modPow(2, m) + MOD - 1) % MOD;

    cout << ans1 * ans2 % MOD << '\n';
    return 0;
}

